using V=std::array<double,3>;
static double magnitude(const V &v){return std::sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]);}
static QJsonArray array(const V &v){return {v[0],v[1],v[2]};}
static V solar(double epoch){auto *s=Moderator::Instance()->GetSolarSystemInUse();const auto sun=s->GetBody("Sun")->GetMJ2000State(A1Mjd(epoch)),earth=s->GetBody("Earth")->GetMJ2000State(A1Mjd(epoch));return {sun[0]-earth[0],sun[1]-earth[1],sun[2]-earth[2]};}
static QJsonObject graph(){QJsonObject r;auto *m=Moderator::Instance();for(const auto &n:m->GetListOfObjects(Gmat::UNKNOWN_OBJECT))if(auto *o=m->GetConfiguredObject(n))r[QString::fromStdString(n)]=QString::fromStdString(o->GetGeneratingString(Gmat::SCRIPTING));return r;}
static ODEModel *forces(){auto *p=dynamic_cast<ODEModel *>(Moderator::Instance()->GetConfiguredObject("Forces"));require(p,"SRP choice ForceModel missing");return p;}
static PhysicalModel *solarForce(ODEModel *m){for(int i=0;i<m->GetNumForces();++i){auto *p=m->GetForce(i);if(p&&p->IsOfType("SolarRadiationPressure"))return p;}return nullptr;}
static QString selected(ODEModel *m){auto *p=solarForce(m);require(p,"SRP choice force missing");return QString::fromStdString(p->GetStringParameter("SRPModel"));}
static void reveal(QWidget *w){require(w,"SRP choice control missing");for(auto *p=w;p;p=p->parentWidget()){for(auto *t:w->window()->findChildren<QTabWidget *>())if(t->indexOf(p)>=0)t->setCurrentWidget(p);if(auto *s=qobject_cast<QScrollArea *>(p))s->ensureWidgetVisible(w);}events();require(w->isVisible()&&w->isEnabled(),"SRP choice control hidden or disabled");acceptanceView(*w);}
static V expected(const QJsonObject &f,const QString &model,const V &sun,const V &position)
{
 V direction{};for(int i=0;i<3;++i)direction[i]=position[i]-sun[i];const double distance=magnitude(direction);
 const double pressure=f["flux_w_m2"].toDouble()/f["light_speed_m_s"].toDouble()*std::pow(f["nominal_sun_km"].toDouble()/distance,2);
 const double factor=pressure/f["dry_mass_kg"].toDouble()/1000.;V result{};
 for(int i=0;i<3;++i){double area=0;
  if(model=="SPADFile")area=f["spad_body_area_m2"].toArray()[i].toDouble()*f["spad_scale"].toDouble();
  else if(model=="NPlate")area=2*f["plate_area_m2"].toDouble()*f["plate_area_coefficient"].toDouble()*direction[i]/distance;
  else area=f["cr"].toDouble()*f["spherical_area_m2"].toDouble()*direction[i]/distance;
  result[i]=factor*area;
 }return result;
}
